import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import BackButton from '../../../components/BackButton';
import type { Comment, Post } from '../../../lib/types';

export const revalidate = 300;
export const dynamicParams = true;

type BlogPostPageProps = {
  params: {
    id: string;
  };
};

async function getPost(id: string): Promise<Post | null> {
  const response = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}`,
    { next: { revalidate: 300 } }
  );

  if (!response.ok) {
    return null;
  }

  return response.json();
}

async function getComments(id: string): Promise<Comment[]> {
  const response = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: 300 } }
  );

  if (!response.ok) {
    return [];
  }

  return response.json();
}

export async function generateStaticParams(): Promise<
  Array<BlogPostPageProps['params']>
> {
  const response = await fetch('https://jsonplaceholder.typicode.com/posts');

  if (!response.ok) {
    return [];
  }

  const posts: Post[] = await response.json();

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }));
}

export async function generateMetadata(
  { params }: BlogPostPageProps
): Promise<Metadata> {
  const post = await getPost(params.id);

  if (!post) {
    return {
      title: 'Post Not Found'
    };
  }

  const description = post.body.substring(0, 160);

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description
    }
  };
}

export default async function BlogPost({ params }: BlogPostPageProps) {
  const post = await getPost(params.id);

  if (!post) {
    notFound();
  }

  const comments = await getComments(params.id);

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

